using System.Globalization;
using System.Text;

namespace TutorFlow.Application.Security;

/// <summary>
/// Normalizacion de las guardias L2a/L2b/L5 (SPEC 6.7): NFD sin diacriticos, minusculas, todo lo que no sea letra
/// o digito pasa a ser un espacio y los espacios se colapsan.
/// </summary>
public static class NormalizadorTexto
{
    public static string Normalizar(string? texto)
    {
        if (string.IsNullOrEmpty(texto))
        {
            return string.Empty;
        }

        var sb = new StringBuilder(texto.Length);
        var espacioPendiente = false;
        foreach (var c in texto.Normalize(NormalizationForm.FormD))
        {
            if (CharUnicodeInfo.GetUnicodeCategory(c) == UnicodeCategory.NonSpacingMark)
            {
                continue;
            }

            if (char.IsLetterOrDigit(c))
            {
                if (espacioPendiente && sb.Length > 0)
                {
                    sb.Append(' ');
                }

                espacioPendiente = false;
                sb.Append(char.ToLowerInvariant(c));
            }
            else
            {
                espacioPendiente = true;
            }
        }

        return sb.ToString();
    }

    public static string[] Palabras(string normalizado) =>
        normalizado.Length == 0 ? [] : normalizado.Split(' ');
}

namespace TutorFlow.Application.Security;

/// <summary>
/// Resultado de una guardia determinista (L2a, L2b o L5). <c>Regla</c> identifica la regla que marco ("R1".."R6",
/// "referencia" en L2a, "salida" en L5); <c>Objetivos</c> son los ids fuera del alcance (para auditoria), vacio en L2b.
/// </summary>
public sealed record ResultadoGuardia(bool Marcada, string? Regla, IReadOnlyList<string> Objetivos)
{
    public static ResultadoGuardia Ninguna { get; } = new(false, null, []);

    public static ResultadoGuardia Marca(string regla, IReadOnlyList<string>? objetivos = null) =>
        new(true, regla, objetivos ?? []);
}

using TutorFlow.Application.Ports;
using TutorFlow.Domain.Authorization;

namespace TutorFlow.Application.Security;

/// <summary>
/// L2a (SPEC 6.2): referencias explicitas a estudiantes del roster (id en variantes de mayusculas y separadores,
/// nombre completo, apellido o nombre de pila UNICOS) y a ids de coordinadores distintos del principal.
/// Funcion pura sobre el texto normalizado; nunca consulta datos academicos ni usa el LLM. Los nombres de
/// coordinadores no se detectan (m8). Los patrones de id se derivan de los ids del roster, sin prefijos fijos.
/// </summary>
public static class GuardiaReferenciasExplicitas
{
    private static readonly HashSet<string> Particulas = new(StringComparer.Ordinal)
    {
        "de", "del", "la", "las", "los", "el", "y", "e", "da", "di", "van", "von", "san",
    };

    /// <summary>Evalua una pregunta del usuario (incluye ids de coordinadores).</summary>
    public static ResultadoGuardia Evaluar(string pregunta, PrincipalAcademico principal, RosterSnapshot roster) =>
        Evaluar(pregunta, principal, roster, incluirCoordinadores: true, regla: "referencia");

    /// <summary>Nucleo compartido con L5: <paramref name="incluirCoordinadores"/> false solo mira estudiantes.</summary>
    internal static ResultadoGuardia Evaluar(
        string texto,
        PrincipalAcademico principal,
        RosterSnapshot roster,
        bool incluirCoordinadores,
        string regla)
    {
        ArgumentNullException.ThrowIfNull(principal);
        ArgumentNullException.ThrowIfNull(roster);

        var normalizado = NormalizadorTexto.Normalizar(texto);
        if (normalizado.Length == 0)
        {
            return ResultadoGuardia.Ninguna;
        }

        var palabras = NormalizadorTexto.Palabras(normalizado);
        var conjunto = new HashSet<string>(palabras, StringComparer.Ordinal);
        var relleno = " " + normalizado + " ";
        var fuera = new List<string>();

        // --- ids (estudiantes y, si aplica, coordinadores) ---
        var estudiantesPorId = new Dictionary<string, RosterEstudiante>(StringComparer.Ordinal);
        foreach (var e in roster.Estudiantes)
        {
            estudiantesPorId[Compacto(e.Id)] = e;
        }

        var coordinadoresPorId = new Dictionary<string, RosterCoordinador>(StringComparer.Ordinal);
        foreach (var c in roster.Coordinadores)
        {
            coordinadoresPorId[Compacto(c.Id)] = c;
        }

        var propio = Compacto(principal.Id);
        var prefijosEstudiante = Prefijos(roster.Estudiantes.Select(e => e.Id));
        var prefijosCoordinador = Prefijos(roster.Coordinadores.Select(c => c.Id));
        AnadirPrefijo(principal.Rol == RolAcademico.Estudiante ? prefijosEstudiante : prefijosCoordinador, propio);

        foreach (var candidato in CandidatosDeId(palabras))
        {
            if (candidato == propio)
            {
                continue;
            }

            if (CoincidePrefijo(candidato, prefijosEstudiante))
            {
                if (estudiantesPorId.TryGetValue(candidato, out var est))
                {
                    if (!EnAlcance(principal, est))
                    {
                        fuera.Add(est.Id);
                    }
                }
                else
                {
                    // Id con forma de estudiante ausente del roster: denegado (SPEC 6.1).
                    fuera.Add(candidato.ToUpperInvariant());
                }
            }
            else if (incluirCoordinadores && CoincidePrefijo(candidato, prefijosCoordinador))
            {
                fuera.Add(coordinadoresPorId.TryGetValue(candidato, out var coord) ? coord.Id : candidato.ToUpperInvariant());
            }
        }

        // --- nombres: completo, o parte unica en el roster ---
        var nombres = roster.Estudiantes
            .Select(e =>
            {
                var nombre = NormalizadorTexto.Normalizar(e.NombreNormalizado);
                return (Est: e, Nombre: nombre, Partes: PartesDeNombre(nombre));
            })
            .ToList();
        var conteo = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (var x in nombres)
        {
            foreach (var parte in x.Partes)
            {
                conteo[parte] = conteo.GetValueOrDefault(parte) + 1;
            }
        }

        foreach (var (est, nombre, partes) in nombres)
        {
            // Una parte del nombre solo se resuelve si es unica en el roster (un nombre ambiguo no se resuelve).
            var mencionado = (nombre.Length > 0 && relleno.Contains(" " + nombre + " ", StringComparison.Ordinal))
                || partes.Any(p => conteo[p] == 1 && conjunto.Contains(p));

            if (mencionado && !EnAlcance(principal, est))
            {
                fuera.Add(est.Id);
            }
        }

        var objetivos = fuera.Distinct(StringComparer.Ordinal).ToList();
        return objetivos.Count == 0 ? ResultadoGuardia.Ninguna : ResultadoGuardia.Marca(regla, objetivos);
    }

    private static bool EnAlcance(PrincipalAcademico principal, RosterEstudiante est) =>
        principal.Rol == RolAcademico.Estudiante
            ? string.Equals(principal.Id, est.Id, StringComparison.Ordinal)
            : principal.ProgramasCoordinados.Contains(est.ProgramaId, StringComparer.Ordinal);

    private static string[] PartesDeNombre(string nombreNormalizado) =>
        NormalizadorTexto.Palabras(nombreNormalizado)
            .Where(p => p.Length >= 3 && !Particulas.Contains(p) && !p.All(char.IsDigit))
            .Distinct(StringComparer.Ordinal)
            .ToArray();

    private static string Compacto(string id) =>
        NormalizadorTexto.Normalizar(id).Replace(" ", string.Empty, StringComparison.Ordinal);

    /// <summary>Prefijo alfabetico de ids con forma letras+digitos (derivado del roster, no fijo).</summary>
    private static HashSet<string> Prefijos(IEnumerable<string> ids)
    {
        var prefijos = new HashSet<string>(StringComparer.Ordinal);
        foreach (var id in ids)
        {
            AnadirPrefijo(prefijos, Compacto(id));
        }

        return prefijos;
    }

    private static void AnadirPrefijo(HashSet<string> prefijos, string compacto)
    {
        var i = 0;
        while (i < compacto.Length && char.IsLetter(compacto[i]))
        {
            i++;
        }

        if (i > 0 && i < compacto.Length && compacto[i..].All(char.IsDigit))
        {
            prefijos.Add(compacto[..i]);
        }
    }

    private static bool CoincidePrefijo(string candidato, HashSet<string> prefijos)
    {
        foreach (var p in prefijos)
        {
            if (candidato.Length > p.Length
                && candidato.StartsWith(p, StringComparison.Ordinal)
                && candidato[p.Length..].All(char.IsDigit))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>Cada palabra y cada par de palabras contiguas, sin separador ("est 002" y "est002" dan "est002").</summary>
    private static IEnumerable<string> CandidatosDeId(string[] palabras)
    {
        for (var i = 0; i < palabras.Length; i++)
        {
            yield return palabras[i];
            if (i + 1 < palabras.Length)
            {
                yield return palabras[i] + palabras[i + 1];
            }
        }
    }
}

using System.Text.RegularExpressions;
using TutorFlow.Application.Ports;
using TutorFlow.Domain.Authorization;

namespace TutorFlow.Application.Security;

/// <summary>
/// L2b (SPEC 6.7, D-03): deteccion lexica y determinista de solicitudes de datos de terceros. Vocabularios TD/ST/SD
/// y reglas R1-R6 exactamente como en SPEC 6.7 (versionados aqui; ampliarlos exige mantener verdes AUTH-06 y AUTH-25).
/// Sin LLM ni puntajes. Se aplica sobre texto normalizado y por palabra completa.
/// </summary>
public static class GuardiaSolicitudesTerceros
{
    public const string VersionVocabularios = "6.7-v1";

    private const string Ini = "(?<![a-z0-9])";
    private const string Fin = "(?![a-z0-9])";

    // TD: dato academico personal.
    private static readonly Regex Td = Construir(
        "nota|notas|promedio|promedios|definitiva|definitivas|calificacion|calificaciones|corte|cortes|falta|faltas|" +
        "inasistencia|inasistencias|asistencia|perdio|perdieron|perdida|perdidas|aprobo|aprobaron|reprobo|reprobaron|" +
        "habilitar|beca|prueba academica|situacion academica|materias perdidas");

    // ST: sujeto de terceros (fuerte).
    private static readonly Regex St = Construir(
        "companero|companeros|companera|companeras|" +
        "otro estudiante|otros estudiantes|otra estudiante|otras estudiantes|" +
        "otra persona|alguien mas|mi amigo|mi amiga|" +
        "todos los estudiantes|todas las estudiantes|" +
        "estudiantes de mi (?:programa|carrera|curso|grupo|semestre|clase|salon)|" +
        "lista(?: completa)? de(?: los)? estudiantes|listado(?: completo)? de(?: los)? estudiantes|" +
        "nombres de los estudiantes|ranking|" +
        "quienes? (?:[a-z0-9]+ ){0,3}(?:perdio|perdieron|reprobo|reprobaron|tiene|tienen|saco|sacaron|falto|faltaron)|" +
        "el estudiante con (?:mas|menos|mejor|peor)|la estudiante con (?:mas|menos|mejor|peor)");

    // SD: sujeto generico (debil).
    private static readonly Regex Sd = Construir("estudiante|estudiantes");

    // R4: otros programas (coordinador).
    private static readonly Regex OtrosProgramas = Construir("otros programas|todos los programas|otra carrera|otras carreras");

    public static ResultadoGuardia Evaluar(string pregunta, PrincipalAcademico principal, RosterSnapshot roster)
    {
        ArgumentNullException.ThrowIfNull(principal);
        ArgumentNullException.ThrowIfNull(roster);

        var normalizado = NormalizadorTexto.Normalizar(pregunta);
        if (normalizado.Length == 0 || !Td.IsMatch(normalizado))
        {
            return ResultadoGuardia.Ninguna;
        }

        // Desde aqui hay TD.
        var td = true;
        var st = St.IsMatch(normalizado);
        var sd = Sd.IsMatch(normalizado);
        var programas = ProgramasReferenciados(normalizado, roster);

        if (principal.Rol == RolAcademico.Estudiante)
        {
            // R1: ST y TD. R2: SD y TD sin ST no marca (pregunta normativa).
            if (st && td)
            {
                return ResultadoGuardia.Marca("R1");
            }

            // R5: cualquier programa (ni siquiera el suyo) con SD o ST y TD.
            if (programas.Count > 0 && (sd || st))
            {
                return ResultadoGuardia.Marca("R5");
            }

            return ResultadoGuardia.Ninguna;
        }

        // Coordinador. R3: ST y TD no marca por si solo (el alcance lo garantizan L2a y L4).
        if (OtrosProgramas.IsMatch(normalizado))
        {
            return ResultadoGuardia.Marca("R4");
        }

        if ((sd || st) && programas.Any(p => !principal.ProgramasCoordinados.Contains(p, StringComparer.Ordinal)))
        {
            return ResultadoGuardia.Marca("R6");
        }

        return ResultadoGuardia.Ninguna;
    }

    private static List<string> ProgramasReferenciados(string normalizado, RosterSnapshot roster)
    {
        var relleno = " " + normalizado + " ";
        var resultado = new List<string>();
        foreach (var p in roster.Programas)
        {
            var porId = NormalizadorTexto.Normalizar(p.Id);
            var porNombre = NormalizadorTexto.Normalizar(p.NombreNormalizado);
            if ((porId.Length > 0 && relleno.Contains(" " + porId + " ", StringComparison.Ordinal))
                || (porNombre.Length > 0 && relleno.Contains(" " + porNombre + " ", StringComparison.Ordinal)))
            {
                resultado.Add(p.Id);
            }
        }

        return resultado;
    }

    private static Regex Construir(string alternativas) =>
        new(Ini + "(?:" + alternativas + ")" + Fin, RegexOptions.CultureInvariant | RegexOptions.Compiled);
}

using TutorFlow.Application.Errores;
using TutorFlow.Application.Ports;
using TutorFlow.Domain.Authorization;

namespace TutorFlow.Application.Security;

/// <summary>
/// L5 (SPEC 6.2): antes de responder, verifica que la respuesta no contenga nombres ni ids de estudiantes fuera del
/// alcance del principal. Determinista; el LLM no interviene. Un hallazgo aborta toda la peticion (403-acceso, "salida").
/// </summary>
public static class GuardiaSalida
{
    public const string Motivo = "salida";

    public static ResultadoGuardia Evaluar(string respuesta, PrincipalAcademico principal, RosterSnapshot roster) =>
        GuardiaReferenciasExplicitas.Evaluar(respuesta, principal, roster, incluirCoordinadores: false, regla: Motivo);

    /// <exception cref="AccesoDenegadoException">La respuesta menciona estudiantes fuera del alcance.</exception>
    public static void Verificar(string respuesta, PrincipalAcademico principal, RosterSnapshot roster, int tokens = 0, decimal costoUsd = 0m)
    {
        if (Evaluar(respuesta, principal, roster).Marcada)
        {
            throw new AccesoDenegadoException(principal.Rol, Motivo, tokens, costoUsd);
        }
    }
}

