                new("EST-001", "laura gomez", "ING-SIS"),
                new("EST-002", "andres martinez", "ING-SIS"),
                new("EST-003", "sofia herrera", "ING-SIS"),
                new("EST-004", "camilo rojas", "ADM"),
                new("EST-005", "valentina castro", "ADM"),
                new("EST-006", "mateo vargas", "ADM"),
